#include "d2u.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int ac,char**av){int sep=-1,i,ns,nt,rc;uint32_t out=0;d2u_runtime r;if(ac<4){fprintf(stderr,"usage: d2u_run_tokens shard1.gguf [shardN.gguf ...] -- token_id [token_id ...]\n");return 2;}for(i=1;i<ac;i++)if(strcmp(av[i],"--")==0){sep=i;break;}if(sep<2||sep==ac-1)return 2;ns=sep-1;nt=ac-sep-1;rc=d2u_runtime_open(&r,0xD2A671Bull,ns,(const char**)&av[1]);if(rc){printf("OPEN=FAIL RC=%d\n",rc);return 3;}{const char*eg=getenv("D2U_EXPERT_CACHE_GIB");if(eg&&*eg){unsigned long long gib=strtoull(eg,0,10);if(gib>0&&gib<=1024)r.expert_cache.budget_bytes=(uint64_t)gib*1024ull*1024ull*1024ull;}}rc=d2u_runtime_enter(&r);if(rc){printf("ENTER=FAIL RC=%d\n",rc);d2u_runtime_close(&r);return 4;}for(i=0;i<nt;i++){uint32_t in=(uint32_t)strtoul(av[sep+1+i],0,10);rc=d2u_runtime_step(&r,in,(uint32_t)i,&out);if(rc){printf("STEP=%d FAIL RC=%d\n",i,rc);break;}printf("STEP=%d INPUT=%u NEXT=%u IO_READS=%llu IO_GIB=%.3f HOTSET_GIB=%.3f CACHE_HIT=%llu MISS=%llu DECODE_AUTH=%u PROMOTE_LOCAL=%u\n",i,in,out,(unsigned long long)r.auth.io_reads,(double)r.auth.io_bytes/(1024.0*1024.0*1024.0),(double)r.expert_cache.used_bytes/(1024.0*1024.0*1024.0),(unsigned long long)r.expert_cache.hits,(unsigned long long)r.expert_cache.misses,r.auth.decode_authority,r.auth.promoted);}
printf("BACKGROUND_SUBMITS=%llu PREDICTIVE_LOADS=%llu REJECTED_IO=%llu\n",(unsigned long long)r.auth.background_submits,(unsigned long long)r.auth.predictive_loads,(unsigned long long)r.auth.rejected_io);d2u_runtime_close(&r);return rc?5:0;}
